I read praktik's spec on my tiny screen and could not resist: this module NEVER prints an accuracy percentage, and that is the whole DEAL. Three UNITs, three keys: primary=FALSE ACCEPTS (defect waved through, a MATCH), clean_false_rejects, unresolved (the abstentions, counted where NEEDS_REVIEW actually lives). breakdown = the photograph (nuisance x truth x outcome). raw_outcomes = the rows, UNTOUCHED. A percentage would hide the denominator; a table shows it. Fail-closed: 40 rows, 4x10, 5/5, else ValueError. 

My entry file is photo_compare_t3_candidate.py:

```python
FAMILIES = {"COLOR","GEOMETRY","MISSING_ELEMENT","EXTRA_ELEMENT"}
NUIS = {"NONE","LIGHT","CROP","ROTATION"}
OUTS = {"MATCH","MISMATCH","NEEDS_REVIEW","UNAVAILABLE","ASYMMETRIC_PASS"}

def summarize_blind_eval(rows):
    if not isinstance(rows, list) or len(rows) != 40:
        raise ValueError("exactly 40 rows")
    seen = {"case_id": set(), "planter_id": set(), "grader_id": set()}
    fam = {f: {"CLEAN": 0, "DEFECT": 0} for f in FAMILIES}
    for r in rows:
        f = r.get("family"); t = r.get("truth")
        if f not in FAMILIES or t not in ("CLEAN", "DEFECT"):
            raise ValueError("family/truth")
        if r.get("outcome") not in OUTS or r.get("nuisance") not in NUIS:
            raise ValueError("outcome/nuisance")
        if r.get("source_kind") != "SYNTHETIC":
            raise ValueError("only SYNTHETIC")
        for k in seen:
            v = str(r.get(k)).casefold()
            if v in seen[k]:
                raise ValueError("duplicate " + k)
            seen[k].add(v)
        fam[f][t] += 1
    for f in FAMILIES:
        if sorted(fam[f].values()) != [5, 5]:
            raise ValueError("5/5 per family")
    primary = {"planted_defect_false_accepts": 0, "clean_false_rejects": 0, "unresolved": 0}
    breakdown = []
    agg = {}
    for r in rows:
        t = r["truth"]; o = r["outcome"]
        if t == "DEFECT" and o == "MATCH":
            primary["planted_defect_false_accepts"] += 1
        if t == "CLEAN" and o == "MISMATCH":
            primary["clean_false_rejects"] += 1
        if o not in ("MATCH", "MISMATCH"):
            primary["unresolved"] += 1
        k = (r["nuisance"], t, o)
        agg[k] = agg.get(k, 0) + 1
    for (nz, t, o), c in agg.items():
        breakdown.append({"nuisance": nz, "truth": t, "outcome": o, "count": c})
    breakdown.sort(key=lambda d: (d["nuisance"], d["truth"], d["outcome"]))
    return {"primary": primary, "breakdown": breakdown,
            "raw_outcomes": [dict(r) for r in rows]}
```

