```python
"""T3c / summarize_blind_eval — счётчик слепой проверки фото, собранный как фотоаппарат.

Форма: код разложен по узлам камеры — корпус, объектив, затвор, матрица, кадр.
Смысл формы: слепая проверка — это одна съёмка, переснять нельзя; плохой
манифест камера не снимает вовсе, а отдаёт ValueError (fail closed).
"""
from collections import defaultdict

# ------------------------------------------------------------------- КОРПУС
# Что вообще имеет право попасть в кадр. Всё, чего здесь нет, — не кадр.
FAMILIES = ("COLOR", "GEOMETRY", "MISSING_ELEMENT", "EXTRA_ELEMENT")
NUISANCES = ("NONE", "LIGHT", "CROP", "ROTATION")
OUTCOMES = ("MATCH", "MISMATCH", "NEEDS_REVIEW", "UNAVAILABLE", "ASYMMETRIC_PASS")
TRUTHS = ("CLEAN", "DEFECT")
SOURCE_KINDS = ("SYNTHETIC",)          # синтетика обязана остаться помеченной

FRAME = 40                             # ровно сорок кадров
PER_FAMILY = 10                        # четыре серии по десять
PER_TRUTH = 5                          # в каждой серии пять чистых и пять с дефектом

ROW_FIELDS = frozenset((
    "case_id", "family", "truth", "outcome", "nuisance", "source_kind",
    "planter_id", "grader_id",
))
RESOLVED = frozenset(("MATCH", "MISMATCH"))


# ----------------------------------------------------------------- ОБЪЕКТИВ
def _снимаем(rows):
    """Объектив: пропускает только целый манифест — сорок кадров, ничего лишнего."""
    if not isinstance(rows, list) or len(rows) != FRAME:
        raise ValueError("манифест обязан быть списком ровно из 40 строк")
    return rows


def _роль(row, field, seen, смысл):
    """Идентификатор роли: непустой, уникальный и различимый без учёта регистра."""
    value = row.get(field)
    if not isinstance(value, str) or not value.strip():
        raise ValueError("%s: пустая роль" % field)
    folded = value.casefold()
    if folded in seen:
        raise ValueError("%s: %s повторяется без учёта регистра" % (field, смысл))
    seen.add(folded)
    return folded


def _проверяем(rows):
    """Проверка кадра до съёмки. Порядок полей не важен, важна полнота."""
    cases, planters, graders = set(), set(), set()
    by_family = defaultdict(list)
    for row in rows:
        if not isinstance(row, dict) or set(row) != ROW_FIELDS:
            raise ValueError("строка манифеста не совпадает по составу полей")
        if row["family"] not in FAMILIES:
            raise ValueError("неизвестное семейство: %r" % (row["family"],))
        if row["truth"] not in TRUTHS:
            raise ValueError("неизвестная правда: %r" % (row["truth"],))
        if row["outcome"] not in OUTCOMES:
            raise ValueError("неизвестный исход: %r" % (row["outcome"],))
        if row["nuisance"] not in NUISANCES:
            raise ValueError("неизвестная помеха: %r" % (row["nuisance"],))
        if row["source_kind"] not in SOURCE_KINDS:
            raise ValueError("источник обязан быть помечен: %r" % (row["source_kind"],))
        _роль(row, "case_id", cases, "дело")
        planter = _роль(row, "planter_id", planters, "раскладчик")
        grader = _роль(row, "grader_id", graders, "оценщик")
        if planter == grader:
            raise ValueError("раскладчик и оценщик — одно лицо: слепая проверка не слепа")
        by_family[row["family"]].append(row)
    if set(by_family) != set(FAMILIES):
        raise ValueError("серии не совпадают с набором семейств")
    for family, group in by_family.items():
        if len(group) != PER_FAMILY:
            raise ValueError("серия %s: строк %d, нужно %d" % (family, len(group), PER_FAMILY))
        for truth in TRUTHS:
            got = sum(1 for row in group if row["truth"] == truth)
            if got != PER_TRUTH:
                raise ValueError("серия %s: %s — %d, нужно %d" % (family, truth, got, PER_TRUTH))
    return rows


# -------------------------------------------------------------------- ЗАТВОР
def _затвор(rows):
    """Затвор: одна вспышка на кадр — исход разложен на три счётчика."""
    planted_defect_false_accepts = 0   # дефект приняли за совпадение
    clean_false_rejects = 0            # чистую вещь отвергли как расхождение
    unresolved = 0                     # всё, что не «совпало» и не «разошлось»
    for row in rows:
        outcome, truth = row["outcome"], row["truth"]
        if outcome not in RESOLVED:
            unresolved += 1
        if truth == "DEFECT" and outcome == "MATCH":
            planted_defect_false_accepts += 1
        if truth == "CLEAN" and outcome == "MISMATCH":
            clean_false_rejects += 1
    return {
        "planted_defect_false_accepts": planted_defect_false_accepts,
        "clean_false_rejects": clean_false_rejects,
        "unresolved": unresolved,
    }


# ------------------------------------------------------------------ МАТРИЦА
def _матрица(rows):
    """Матрица: полный разрез помеха × правда × исход, включая пустые клетки."""
    grid = {
        nuisance: {
            truth: {outcome: 0 for outcome in OUTCOMES}
            for truth in TRUTHS
        }
        for nuisance in NUISANCES
    }
    for row in rows:
        grid[row["nuisance"]][row["truth"]][row["outcome"]] += 1
    return grid


# --------------------------------------------------------------------- КАДР
def summarize_blind_eval(rows):
    """Снять один кадр: primary, breakdown, raw_outcomes — и ничего больше."""
    rows = _снимаем(rows)
    rows = _проверяем(rows)
    return {
        "primary": _затвор(rows),
        "breakdown": _матрица(rows),
        "raw_outcomes": rows,
    }
```

